    if(elev){progress('正在联网读取高程瓦片…',8);const e=await loadTerrain(bbox,width,height,run.signal,n=>progress('正在联网读取高程瓦片… '+Math.round(n*100)+'%',8+n*42));grid.dem=e.values;grid.demZoom=e.zoom}
